def implies(p, q):
    return not p or q

def report(case, name, first):
    if first == 0:
        print(f"Case {case}: {name}: true for every n from 1 to 12")
    else:
        print(f"Case {case}: {name}: fails first at n = {first}")

first = [0, 0, 0, 0]
for n in range(1, 13):
    p = n % 4 == 0
    q = n % 2 == 0
    forms = [implies(p, q), implies(q, p), implies(not p, not q), implies(not q, not p)]
    for k in range(4):
        if not forms[k] and first[k] == 0:
            first[k] = n
report("1 · original", "if divisible by 4, then even", first[0])
report("2 · converse", "if even, then divisible by 4", first[1])
report("3 · inverse", "if not divisible by 4, then odd", first[2])
report("4 · contrapositive", "if odd, then not divisible by 4", first[3])

from itertools import product

def implies(p, q):
    return not p or q

def compare(case, k):
    print(f"Case {case}")
    first = ""
    for p, q, r in product([True, False], repeat=3):
        if k == 1:
            left = not (p and q)
            right = not p or not q
        elif k == 2:
            left = not (p and q)
            right = not p and not q
        elif k == 3:
            left = implies(p, q)
            right = implies(not q, not p)
        else:
            left = p and (q or r)
            right = (p and q) or (p and r)
        if left != right and first == "":
            first = f"p {p}, q {q}, r {r}: {left} against {right}"
    if first == "":
        print("  the same in all 8 rows: equivalent")
    else:
        print(f"  not equivalent, first differs at {first}")

compare("1 · De Morgan for and", 1)
compare("2 · the trap: no flip", 2)
compare("3 · the contrapositive", 3)
compare("4 · and over or", 4)

