from itertools import product

def implies(p, q):
    return not p or q

def pair(k, p, q, r):
    if k == 1:
        return not (p and q), not p or not q
    elif k == 2:
        return not (p or q), not p and not q
    elif k == 3:
        return not (p and q), not p and not q
    elif k == 4:
        return implies(p, q), not p or q
    elif k == 5:
        return implies(p, q), implies(not q, not p)
    elif k == 6:
        return implies(p, q), implies(q, p)
    elif k == 7:
        return p or (q and r), (p or q) and (p or r)
    return not implies(p, q), implies(p, not q)

count = int(input())
for j in range(count):
    k = int(input())
    first = ""
    for p, q, r in product([True, False], repeat=3):
        left, right = pair(k, p, q, r)
        if left != right and first == "":
            first = f"p {p}, q {q}, r {r}"
    if first == "":
        print(f"pair {k}: equivalent")
    else:
        print(f"pair {k}: not equivalent, first differs at {first}")
